-- ============================================================
-- garment_variants: clothing category × attribute combinations
-- Each row is a unique (category, material, fill_type, thickness,
-- fit_type, bodysuit_style, pant_length, sock_height) tuple with
-- a single warmth_value and editable C-end labels.
-- Spec: docs/specs/garment-variants.md
-- Seed: auto-generated by packages/core/src/generate-migration-seed.ts
-- ============================================================

-- 1. Table
create table if not exists public.garment_variants (
  id              uuid primary key default gen_random_uuid(),
  category_id     uuid references public.categories(id) on delete cascade,
  category_code   text not null,
  material        text,
  fill_type       text,
  thickness       text,
  fit_type        text,
  bodysuit_style  text,
  pant_length     text,
  sock_height     text,
  warmth_value    smallint not null check (warmth_value >= 0 and warmth_value <= 100),
  admin_label     text not null,
  consumer_label  text not null,
  consumer_tags   text[] not null default '{}',
  is_active       boolean not null default true,
  sort_order      integer not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint garment_variants_admin_label_not_empty check (char_length(trim(admin_label)) > 0),
  constraint garment_variants_consumer_label_not_empty check (char_length(trim(consumer_label)) > 0)
);

comment on table public.garment_variants is '服装细类型：品类×属性组合，每行含单点保暖值与 C 端文案；spec: docs/specs/garment-variants.md';
comment on column public.garment_variants.warmth_value is '单点保暖分 0-100，对齐 requiredWarmth；选衣取最近值';
comment on column public.garment_variants.admin_label is 'B 端身份标识，代码生成，只读';
comment on column public.garment_variants.consumer_label is 'C 端展示文案，后台可改';
comment on column public.garment_variants.consumer_tags is 'C 端属性芯片，后台可改';

-- Unique combination
alter table public.garment_variants
  drop constraint if exists garment_variants_unique_attrs;
alter table public.garment_variants
  add constraint garment_variants_unique_attrs unique nulls not distinct
  (category_id, material, fill_type, thickness, fit_type, bodysuit_style, pant_length, sock_height);

-- Indexes
create index if not exists garment_variants_category_code_active_idx
  on public.garment_variants (category_code, is_active, warmth_value)
  where is_active = true;

create index if not exists garment_variants_category_id_idx
  on public.garment_variants (category_id, is_active, warmth_value);

-- updated_at trigger
drop trigger if exists garment_variants_updated_at on public.garment_variants;
create trigger garment_variants_updated_at
  before update on public.garment_variants
  for each row execute function public.set_updated_at();

-- 2. RLS
alter table public.garment_variants enable row level security;

drop policy if exists "garment_variants_select_active" on public.garment_variants;
create policy "garment_variants_select_active"
  on public.garment_variants for select
  using (is_active = true);

drop policy if exists "garment_variants_select_authenticated" on public.garment_variants;
create policy "garment_variants_select_authenticated"
  on public.garment_variants for select
  to authenticated
  using (true);

